var i=[{title:`Stima il tuo raggio sopra la testa`,text:`Stai in piedi sulla superficie su cui ti allenerai e porta le braccia sopra la testa in modo naturale. Poi aggiungi l’altezza del manubrio, della kettlebell, del bilanciere o di un altro attrezzo sopra le mani. Lascia spazio per un movimento controllato, in modo che l’oggetto non si fermi mai appena sotto il soffitto.`},{title:`Il movimento richiede più dell’altezza in piedi`,text:`Il salto aggiunge spostamento verticale, e una corda per saltare passa sopra la testa. Le trazioni richiedono spazio sopra la sbarra per la testa e sotto per i piedi, e anche le sbarre da stipite richiedono un’altezza libera sicura dove si fissano. Ventilatori a soffitto, luci, tubature e travi a vista possono ridurre l’altezza che puoi davvero usare.`},{title:`Prova il movimento a vuoto`,text:`Se il soffitto sembra abbastanza alto, esegui il movimento senza carico e controlla il punto più alto da una posizione sicura. Non provare mai sollevando qualcosa di pesante verso un soffitto basso. Anche una persona bassa può avere bisogno di più spazio del previsto, perché l’attrezzo viaggia sopra le mani.`},{title:`Sostituzioni pratiche`,text:`Sotto un soffitto basso, le distensioni a terra possono sostituire quelle sopra la testa, e i rematori possono sostituire le trazioni se l’installazione o lo spazio libero della sbarra non sono adatti. Per il condizionamento, scegli marcia, step-up o shadow boxing al posto di corda per saltare o jumping jack con le braccia sopra la testa. Questi scambi potrebbero non allenare esattamente la stessa azione articolare, ma mantengono l’obiettivo della sessione.`},{title:`Usare TrainUp`,text:`Inserisci in Profilo l’altezza del soffitto insieme alle dimensioni del pavimento. Il piano esclude gli esercizi sopra la testa e con salti che richiedono più spazio libero di quello che hai.`}];var o=[{label:`Libreria di esercizi ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: sicurezza e tecnica dell’allenamento coi pesi`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:i,sources:o};export{t as default,i as sections,o as sources};